"""## **2.LLM**
Definiremos nuestro LLM. Este sera obtenido de un proceso de fine-tunnig apartir de GPT3.5-turbo-16k

### Fine - Tuning ###

En esta sección haremos Fine-Tuning a nuestro modelo. Para esto primero implementaremos ciertas funciones para preprocesar nuestros datos, posteirormente prepocesaremos los datos con hugging Face, y finalmente haremos el fine tuning.

#### Preprocesamiento con phyton ####
"""

import pandas as pd

archivo_inicial = "/content/ArchivoInicialUno.xlsx"

df = pd.read_excel(archivo_inicial)

#Eliminamos las filas sin hecho victimizante:
df = df.dropna(subset=["Hecho Victimizante"]).reset_index(drop=True)

#Y también las que no tienen información importante:
columnas_a_mantener = ['Código Víctima Principal', 'Hecho Victimizante','Fecha Inicio Hecho',
                       'Fecha Fin Hecho','Departament o Hechos','Municipio Hechos',
                       'Lugar Hechos','Bloque']
df = df.filter(items=columnas_a_mantener)
df

"""Para poder identificar los testimonios que se complementan, es decir, que están divididos en varias filas, usaremos la siguiente función que identifica los intervalos en los que los testimonios se complementan para luego ser unidos por otra función."""

def intervalos(datafra):

  dic = {}  # Diccionario índice fila: índices filas nulas antes de la fila

  # Encuentra los índices de filas no nulas en "Código Víctima Principal"
  no_nulas = [i for i, val in enumerate(datafra["Código Víctima Principal"].notna()) if val]

  # Crea un diccionario de intervalos
  for i in range(len(no_nulas) - 1):
      dic[no_nulas[i]] = list(range(no_nulas[i], no_nulas[i+1]))

  # Asegurémonos de agregar también el último intervalo
  if no_nulas:
      dic[no_nulas[-1]] = list(range(no_nulas[-1], len(datafra)))

  return dic

  #Aplicamos nuestra función:
inter = intervalos(df)

"""Ahora implementamos la función para poder juntar las filas con los mismos testimonios según los intervalos anteriores:"""

def juntar(df,inter):
    # Crea un nuevo DataFrame para almacenar el resultado
    resultado = pd.DataFrame(columns=df.columns)

    # Itera a través de los intervalos en el diccionario
    for llave, intervalo in inter.items():
        # Obtiene la primera fila del intervalo
        primera_fila = df.iloc[intervalo[0]]

        # Para las columnas que no son "Hecho Victimizante", toma los valores de la primera fila
        for columna in df.columns:
            if columna != "Hecho Victimizante":
                primera_fila[columna] = df.at[intervalo[0], columna]

        # Para la columna "Hecho Victimizante", concatena los valores que son strings
        hecho_victimizante = " ".join(str(valor) for valor in df.loc[intervalo, "Hecho Victimizante"] if isinstance(valor, str))
        primera_fila["Hecho Victimizante"] = hecho_victimizante

        # Agrega la primera fila del intervalo al DataFrame de resultado
        resultado = pd.concat([resultado, primera_fila.to_frame().T], ignore_index=True)

    return resultado

dfinal = juntar(df = df, inter = inter)

"""Seguiremos preprocesando los textos:"""

dfinal

textos = dfinal["Hecho Victimizante"]

"""Usaremos regrex para eliminar palabras inncesarias y espacios dobles:"""

import re


def eliminar_palabras(patrones, texto):
    for patron in patrones:
        texto = re.sub(patron, '', texto)
    return texto

patrones = [r'\([^)]*\)',r'\b[Cc]\.[Cc]\. \w+\b|\b[Cc][Cc] \w+\b']

textos_procesados = textos.apply(lambda x: eliminar_palabras(patrones, x))

textos_procesados = textos_procesados.apply(lambda x: eliminar_palabras([r'(?<!\w)  ',r'(?<![A-Za-z0-9]),'], x))

print(textos_procesados)

"""Ahora juntaremos la columna de municipio hechos y la columna preprocesada anteriormente."""

dft = pd.concat([textos_procesados, dfinal['Municipio Hechos']], axis=1)

"""Llenamos los valores nulos de la segunda columna:"""

dft['Municipio Hechos'] = dft['Municipio Hechos'].apply(lambda x: 'No Informado' if pd.isna(x) or not isinstance(x, str) else x)

dft

