from datasets import load_dataset
from IPython.display import display
from transformers import (
        GPT2Tokenizer, GPT2Config, GPT2LMHeadModel,
        TrainingArguments, Trainer, DataCollatorForLanguageModeling,
        pipeline
        )

"""Importamos el dataset con datasets. Primero combertimos nuestro dataframe a un formato compatible con HuggingFace y luego lo cargamos como un dataset de HuggingFace:"""

from datasets import Dataset

data_dict = {'Hecho Victimizante': dft['Hecho Victimizante'], "Municipio Hechos": dft['Municipio Hechos']}
ds = Dataset.from_dict(data_dict)

"""Ahora crearemos una nueva columna, esta sera "Hecho Total" y sera la unión de las columnas ya existentes:"""

ds_nuevo = ds.map(
    lambda sample: {
        "Hecho Total": f"{sample['Municipio Hechos']}: \n {sample['Hecho Victimizante']}"
    },
    remove_columns= ['Municipio Hechos','Hecho Victimizante']
    )

"""Veamos las columnas y el número de filas de nuestro nuevo DataFrame"""

display(ds_nuevo.column_names)
display(ds_nuevo.num_rows)

"""#### Entrenamiento ####

Primero partiremos nuestro dataframe en entrenamiento y prueba
"""

partition_ds = ds_nuevo.train_test_split(test_size=0.3, seed=41)

display(partition_ds.keys())

"""Ahora aplicaremos nuestro tokenizador"""

tokenizer = GPT2Tokenizer.from_pretrained('gpt2')

def tokenize(sample):
    inputs = tokenizer(sample["Hecho Total"], truncation=True, max_length=512, padding="max_length")
    return {"input_ids": inputs["input_ids"]}

tokenizer.pad_token = tokenizer.eos_token
ds_token = partition_ds.map(
    tokenize, remove_columns=ds_nuevo.column_names, num_proc=4
).with_format("torch")

"""Ahora importaremos el modelo:"""

config = GPT2Config.from_pretrained(
    "gpt2",
    n_ctx=512,
)

model = GPT2LMHeadModel(config).to("cuda")

"""Definimos los argumentos del entrenamiento:"""

args = TrainingArguments(
    output_dir="gpt3_conflic",
    per_device_train_batch_size=16,
    per_device_eval_batch_size=16,
    evaluation_strategy="steps",
    num_train_epochs=5,
    warmup_steps=1_000,
    fp16=True,
    learning_rate=1e-4,
    save_strategy="epoch",
)

from transformers import Trainer

tokenizer.pad_token = tokenizer.eos_token
data_collator = DataCollatorForLanguageModeling(tokenizer, mlm=False)
trainer = Trainer(
    model=model,
    tokenizer=tokenizer,
    args=args,
    data_collator=data_collator,
    train_dataset=ds_token["train"],
    eval_dataset=ds_token["test"]
)
trainer.train()

